import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { parallaxScroll, depthRotate } from '@/primitives';

export default function createNode(config, ctx) {
  const root = new Group();

  // Geometry
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Material
  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.6;
  material.metalness = 0.2;
  material.clearcoat = 0.1;
  material.displacementScale = 0.2;

  // Load textures asynchronously
  let colorTex, depthTex;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colorTex = tex;
    material.map = tex;
    material.needsUpdate = true;
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthTex = tex;
    material.displacementMap = tex;
    material.needsUpdate = true;
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Cinematic primitives
  const primitives = [];

  const parallax = ctx.primitives['parallax-scroll']?.(root, { intensity: 0.4 });
  if (parallax) primitives.push(parallax);

  const rotate = ctx.primitives['depth-rotate']?.(root, { maxDeg: 8 });
  if (rotate) primitives.push(rotate);

  // Interaction handlers
  root.userData.handlers = {};

  // Hover effect: rise-in (subtle, 0.15 units)
  const hoverEnter = () => {
    const tl = gsap.timeline({ onComplete: () => (root.userData._hoverTimeline = null) });
    tl.to(root.position, { y: root.position.y + 0.15, duration: 0.15, ease: 'power3.out' });
    root.userData._hoverTimeline = tl;
  };
  const hoverLeave = () => {
    if (root.userData._hoverTimeline) {
      root.userData._hoverTimeline.reverse();
      root.userData._hoverTimeline = null;
    } else {
      gsap.to(root.position, { y: root.position.y - 0.15, duration: 0.15, ease: 'power3.out' });
    }
  };
  root.userData.handlers.hover = hoverEnter;
  root.userData.handlers['hover-out'] = hoverLeave;

  // Click effect: emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-pricing.select', {});
  };

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    if (colorTex) colorTex.dispose();
    if (depthTex) depthTex.dispose();

    // Cleanup primitives
    primitives.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });

    // Kill GSAP timelines
    if (root.userData._hoverTimeline) {
      root.userData._hoverTimeline.kill();
      root.userData._hoverTimeline = null;
    }
  };

  return root;
}
